async function refresh(){if(!mobile)return;if(!base){showPair('Enter the secure Remote Access URL shown by Yardmaster on your PC.');return}const health=await tunnelHealth();if(!health.ok){showPair(health.error);return}if(!deviceId||!token){showPair(deviceId?'Tunnel reached. Unlock with your passkey, or Pair This Phone Again.':'Tunnel reached. Enter the fresh six-digit pairing code from the PC.');return}try{const authenticated=await api('/api/status');render(authenticated);await renderMobileIntelligence();hidePair();const needsRepair=('Notification' in window)&&Notification.permission==='granted'&&localStorage.getItem(KEY+'push-enabled')==='1'&&(!authenticated.currentDevice?.hasPush||String(authenticated.currentDevice?.pushStatus||'')!=='working');if(needsRepair&&!pushRepairBusy&&Date.now()-lastSilentPushRepair>60000){lastSilentPushRepair=Date.now();ensurePush({requestPermission:false,test:true,force:true,silent:true})}}catch(error){showPair(error.message||'Remote authentication failed.')}}
$('#unlock')?.addEventListener('click',unlockWithPasskey);$('#pair')?.addEventListener('click',async()=>{const u=$('#url').value.trim().replace(/\/$/,''),code=$('#code').value.trim(),device=$('#device').value.trim()||'My phone';if(!validRemote(u)){$('#pairMsg').textContent='Use the HTTPS trycloudflare.com URL shown by Yardmaster.';return}if(!navigator.credentials){$('#pairMsg').textContent='This device does not support passkeys.';return}$('#pairMsg').textContent='Checking tunnel…';try{base=u;localStorage.setItem(KEY+'url',u);const health=await tunnelHealth();if(!health.ok)throw new Error(health.error);$('#pairMsg').textContent='Creating passkey…';const r=await fetch(u+'/api/passkey/register/options',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code,deviceName:device})});if(!r.ok)throw new Error(await r.text());const j=await r.json(),cred=await navigator.credentials.create({publicKey:regOptions(j.options)});const vr=await fetch(u+'/api/passkey/register/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({registrationId:j.registrationId,credential:serializeRegistration(cred)})});if(!vr.ok)throw new Error(await vr.text());const v=await vr.json();base=u;deviceId=v.deviceId;token=v.sessionToken;localStorage.setItem(KEY+'url',u);localStorage.setItem(KEY+'deviceId',deviceId);sessionStorage.setItem(KEY+'session',token);history.replaceState(null,'','/yardmaster');hidePair();refresh()}catch(e){$('#pairMsg').textContent='Pairing failed: '+e.message}});
document.addEventListener('click',async e=>{const b=e.target.closest?.('[data-act]');if(!b)return;try{const result=await api('/api/action',{method:'POST',body:JSON.stringify({action:b.dataset.act})});if(b.dataset.act==='update-operator-now'){if(result.queued)$('#mUpdateMessage').textContent='Update queued. Waiting on '+result.waitingOn+'. Yardmaster will update at the safe point and resume afterward.';else if(result.current)$('#mUpdateMessage').textContent='This PC is already on the current verified Yardmaster release.';else if(result.started)$('#mUpdateMessage').textContent='PC update started. Yardmaster will restart and reconnect.'}refresh()}catch(err){alert(err.message)}});
for(const [id,key,type] of [['branch','branch','text'],['repositoryPath','repositoryPath','text'],['testingUrl','testingUrl','text'],['testType','testType','text'],['chatMode','chatMode','text'],['model','model','text'],['thinkingEffort','thinkingEffort','text'],['chatLoopEnabled','chatLoopEnabled','bool'],['chatLoopPlan','chatLoopPlan','text'],['repoMode','repoUpdateMode','text'],['maxRepairs','maxRepairAttempts','number'],['maxSelfHeal','maxSelfHealAttempts','number'],['autoHandoff','autoHandoff','bool'],['autoSelfHeal','autoSelfHeal','bool'],['autoPush','autoPush','bool'],['waitDeploy','waitForDeploy','bool'],['runAfterDeploy','runAfterDeploy','bool'],['autoUpdateOperator','autoUpdateOperator','bool'],['dryRunMode','dryRunMode','bool']])$('#'+id)?.addEventListener('change',async e=>{let value=e.target.value;if(type==='number')value=Number(value);if(type==='bool')value=value==='true';try{await api('/api/config',{method:'POST',body:JSON.stringify({[key]:value})});refresh()}catch(err){alert(err.message)}});
$('#consoleAutoScroll')?.addEventListener('click',()=>{consoleAutoScroll=!consoleAutoScroll;$('#consoleAutoScroll').textContent='Auto-scroll: '+(consoleAutoScroll?'On':'Off');if(consoleAutoScroll&&$('#mConsole'))$('#mConsole').scrollTop=$('#mConsole').scrollHeight});
$('#copyConsole')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('#mConsole')?.textContent||'');const b=$('#copyConsole');b.textContent='Copied';setTimeout(()=>b.textContent='Copy',900)}catch{alert('Could not copy the console output on this browser.')}});
for(const button of [$('#mobileNewWorkControl'),$('#mobileNewWork')])button?.addEventListener('click',()=>$('#newWorkOverlay')?.classList.add('show'));
$('#cancelMobileWork')?.addEventListener('click',()=>$('#newWorkOverlay')?.classList.remove('show'));
$('#submitMobileWork')?.addEventListener('click',async()=>{const task=$('#mobileWorkTask')?.value.trim()||'',message=$('#mobileWorkMsg'),button=$('#submitMobileWork');if(!task){message.textContent='Describe what you want implemented first.';return}try{button.disabled=true;button.textContent='Handing off…';const accepted=await api('/api/action',{method:'POST',body:JSON.stringify({action:'new-implementation',taskPrompt:task,pushWhenPassed:!!$('#mobileWorkPush')?.checked})});if(accepted?.runsOn!=='windows-pc')throw new Error('The Windows Yardmaster did not confirm the remote job.');message.textContent='Accepted by your Windows Yardmaster. The PC is running this work now.';$('#mobileWorkTask').value='';setTimeout(()=>$('#newWorkOverlay')?.classList.remove('show'),650);await refresh()}catch(error){message.textContent=error.message}finally{button.disabled=false;button.textContent='Hand Off & Walk Away'}});
document.addEventListener('click',async e=>{
  const tab=e.target.closest?.('[data-mobile-section-target]');if(tab){const target=tab.dataset.mobileSectionTarget;document.querySelectorAll('.mobile-nav [data-mobile-section-target]').forEach(x=>x.classList.toggle('active',x===tab));document.querySelectorAll('.m-section[data-mobile-section]').forEach(x=>x.classList.toggle('active',x.dataset.mobileSection===target));if(target==='intelligence')await renderMobileIntelligence();window.scrollTo({top:0,behavior:'instant'});return}
  const ev=e.target.closest?.('[data-evidence-id]');if(ev){try{await downloadEvidence(ev.dataset.evidenceId,ev.dataset.evidenceName)}catch(err){alert(err.message)}return}
  const b=e.target.closest?.('[data-mobile-action]');if(!b)return;let body={action:b.dataset.mobileAction};
  if(body.action==='add-note'){body={action:'add-run-note',note:$('#mRunNote').value.trim()}}
  else if(body.action==='bookmark'){body={action:'bookmark-run',note:$('#mRunNote').value.trim(),bookmark:true}}
  else if(body.action==='toggle-safe'){body={action:'set-safe-mode',enabled:!mobileIntel.safeMode?.enabled,reason:'mobile control'}}
  else if(body.action==='save-profile'){body={action:'save-profile',name:$('#mProfileName').value.trim()||'Mobile Profile'}}
  else if(body.action==='apply-profile'||body.action==='delete-profile')body.key=b.dataset.key;
  else if(body.action==='create-worktree'){body={action:'create-worktree',branch:$('#mWorktreeBranch').value.trim(),base:'HEAD'}}
  else if(body.action==='remove-worktree')body.path=b.dataset.path;
  else if(body.action==='revoke-device')body={action:'revoke-device',deviceId:b.dataset.deviceId};
  try{await api('/api/action',{method:'POST',body:JSON.stringify(body)});await refresh()}catch(err){alert(err.message)}
});

$('#mSendProtocol')?.addEventListener('click',async()=>{const text=$('#mProtocol').value.trim();if(!text)return;try{await api('/api/command',{method:'POST',body:JSON.stringify({text})});$('#mProtocol').value='';await refresh()}catch(e){alert(e.message)}});
$('#mRefreshIntel')?.addEventListener('click',renderMobileIntelligence);
if(mobile){for(const type of ['gesturestart','gesturechange','gestureend'])document.addEventListener(type,e=>e.preventDefault(),{passive:false});document.addEventListener('touchmove',e=>{if(e.touches?.length>1)e.preventDefault()},{passive:false});}

refresh();setInterval(refresh,2500);
